Q: Can I use WASAPI in C code on MinGW64? If so, how? A: <p>I ran into this problem while developing a C audio app for Windows. Based on einpoklum's answer, I decided not to try using C on MinGW64, and tried instead using G++ on MinGW64.  Here is a complete AudioRecorder class that compiles using G++ and runs successfully</p>
<pre><code>#include &quot;audio_recorder.h&quot;
#include &quot;audio_clipper.h&quot;
#include &lt;iostream&gt;
#include &lt;stdexcept&gt;
#include &lt;wrl.h&gt;
#include &lt;audioclient.h&gt;
#include &lt;mmdeviceapi.h&gt;
#include &lt;vector&gt;
#include &lt;ksmedia.h&gt;
#include &lt;stdint.h&gt;
#include &lt;Functiondiscoverykeys_devpkey.h&gt;

using namespace Microsoft::WRL;

// -----------------------------------------------------------------------------------------------------
bool showDeviceName (ComPtr&lt;IMMDevice&gt; device) {
    HRESULT hr = S_OK;
    LPWSTR pwszID = NULL;
    IPropertyStore *pProps = NULL;


        hr = device-&gt;GetId(&amp;pwszID);
        if (hr != S_OK) {
            printf (&quot;GetId failed (%ld\n&quot;, hr);
            return false;
        }

        hr = device-&gt;OpenPropertyStore(STGM_READ, &amp;pProps);

        PROPVARIANT varName;
        // Initialize container for property value.
        PropVariantInit(&amp;varName);

        // Get the endpoint's friendly-name property.
        hr = pProps-&gt;GetValue(
                       PKEY_Device_FriendlyName, &amp;varName);
        if (hr != S_OK) {
            printf (&quot;GetValue failed (%ld\n&quot;, hr);
            return false;
        }

        // GetValue succeeds and returns S_OK if PKEY_Device_FriendlyName is not found.
        // In this case vartName.vt is set to VT_EMPTY.      
        if (varName.vt != VT_EMPTY)
        {
            // Print endpoint friendly name and endpoint ID.
            printf(&quot;Endpoint \&quot;%S\&quot; (%S)\n&quot;, varName.pwszVal, pwszID);
        }

        CoTaskMemFree(pwszID);
        pwszID = NULL;
        PropVariantClear(&amp;varName);
        return true;
}



// -----------------------------------------------------------------------------------------------------
AudioRecorder::AudioRecorder() : audioClient(nullptr), captureClient(nullptr), isRecording(false) {
    // Initialize COM library
    CoInitialize(nullptr);
}

// -----------------------------------------------------------------------------------------------------
AudioRecorder::~AudioRecorder() {
    stopRecording();
    if (audioClient) {
        audioClient-&gt;Release();
    }
    CoUninitialize();
}

// -----------------------------------------------------------------------------------------------------
bool AudioRecorder::initialize() {
    HRESULT hr = S_OK;

    // Get the default audio device
    ComPtr&lt;IMMDeviceEnumerator&gt; deviceEnumerator;
    hr = CoCreateInstance(__uuidof(MMDeviceEnumerator), nullptr, CLSCTX_ALL, IID_PPV_ARGS(&amp;deviceEnumerator));
    if (hr != S_OK) {
        printf (&quot;CoCreateInstance failed (%lx\n&quot;, hr);
        return false;
    }

    ComPtr&lt;IMMDevice&gt; device;
    hr = deviceEnumerator-&gt;GetDefaultAudioEndpoint(eCapture, eConsole, &amp;device);
    if (hr != S_OK) {
        printf (&quot;Activate failed (%lx\n&quot;, hr);
        return false;
    }

    showDeviceName (device);

    // Initialize the audio client
    hr = device-&gt;Activate(__uuidof(IAudioClient), CLSCTX_ALL, nullptr, reinterpret_cast&lt;void**&gt;(&amp;audioClient));
    if (hr != S_OK) {
        printf (&quot;Activate failed (%lx\n&quot;, hr);
        return false;
    }

    WAVEFORMATEX * waveFormat;
    audioClient-&gt;GetMixFormat(&amp;waveFormat);
    printf (&quot;ft %d nc %d sr %ld bits %d\n&quot;, waveFormat-&gt;wFormatTag, waveFormat-&gt;nChannels, waveFormat-&gt;nSamplesPerSec, waveFormat-&gt;wBitsPerSample);

    if (waveFormat-&gt;nSamplesPerSec != SAMPLE_RATE) {
        printf (&quot;Incorrect sample rate (%ld vs %d)\n&quot;, waveFormat-&gt;nSamplesPerSec, SAMPLE_RATE);
        return false;
    }

//  waveFormat-&gt;wFormatTag = WAVE_FORMAT_PCM; // leave it set to WAVE_FORMAT_EXTENSIBLE
//   waveFormat-&gt;nChannels = 1; // Mono
//    waveFormat-&gt;nSamplesPerSec = 48000; // Sample rate
//    waveFormat-&gt;wBitsPerSample = 32; // Bits per sample
//    waveFormat-&gt;nBlockAlign = waveFormat-&gt;nChannels * (waveFormat-&gt;wBitsPerSample / 8);
//    waveFormat-&gt;nAvgBytesPerSec = waveFormat-&gt;nSamplesPerSec * waveFormat-&gt;nBlockAlign;

    hr = audioClient-&gt;Initialize(AUDCLNT_SHAREMODE_SHARED, 0, 10000000, 0, waveFormat, nullptr);
    if (hr != S_OK) {
        printf (&quot;Initialize failed (%lx\n&quot;, hr);
        return false;
    }

    hr = audioClient-&gt;GetService (IID_PPV_ARGS(&amp;captureClient));
    if (hr != S_OK) {
        printf (&quot;GetService failed (%ld\n&quot;, hr);
        return false;
    }

    CoTaskMemFree(waveFormat);
    return true;
}

// ----------------------------------------------------------------------------------
bool AudioRecorder::startRecording() {
    HRESULT hr;
    if (isRecording) return true;

    hr = audioClient-&gt;Start();
    if (hr != S_OK) {
        printf (&quot;Start failed (%lx\n&quot;, hr);
        return false;
    }
    isRecording = true;
    return true;
}

// --------------------------------------------------------------------------------
void AudioRecorder :: setClipper (AudioClipper * clipper) {
    this-&gt;clipper = clipper;
}


// ---------------------------------------------------------------------------------
bool AudioRecorder::getNewData () {
    HRESULT hr;
    UINT32 numFramesAvailable;
    BYTE * data;
    DWORD flags;

    numFramesAvailable = 0;
    hr = captureClient-&gt;GetBuffer(&amp;data, &amp;numFramesAvailable, &amp;flags, nullptr, nullptr);
    if (hr != S_OK) {
        printf (&quot;GetBuffer failed (%lx)\n&quot;, hr);
    }
    if (numFramesAvailable &gt; 0) {
        clipper-&gt;addFrames ((float *) data, numFramesAvailable);
    }
    captureClient-&gt;ReleaseBuffer(numFramesAvailable);

    return true;
}

// -----------------------------------------------------------------------------------
bool AudioRecorder::stopRecording() {
    if (!isRecording) 
        return true;

    audioClient-&gt;Stop();
    isRecording = false;
    return true;
}

</code></pre>
